import { createRequire } from 'node:module';
import type { ScvalDecoder } from '@/lib/decode';

/**
 * Test helper: the SAME pinned WASM artifact the browser loads, but through its
 * nodejs target. Generated by `npm run test:unit`'s pretest step from
 * vendor/sgg-parser-wasm-0.1.0-alpha.1.tgz (sha256 checked against parser.lock).
 *
 * No mock decoder exists in this repo: tests exercise the real wasm-bindgen
 * build, so a broken pin or a broken export fails the suite.
 */
const require = createRequire(import.meta.url);
const wasm = require('../../generated/wasm/nodejs/sgp_parser_wasm.js') as {
  decode_scval_base64(xdrBase64: string): string;
};

export const nodeParserWasm: ScvalDecoder = {
  decodeScval(base64: string): unknown {
    return JSON.parse(wasm.decode_scval_base64(base64)) as unknown;
  },
};
